// ***************
// Filename: object_tracker_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of object_tracker: joins the register map
//   object_tracker_regs (modport regs) and the logic object_tracker (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   object_tracker_regs.json: edit the JSON and regenerate.
// Date: 2026-10-16
interface object_tracker_regs_if ();
  logic [32-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [32-1:0] cfg_frame_size;
  logic cfg_frame_size_wr;
  logic [8-1:0] cfg_thresh;
  logic cfg_thresh_wr;
  logic [32-1:0] cfg_win_x;
  logic cfg_win_x_wr;
  logic [32-1:0] cfg_win_y;
  logic cfg_win_y_wr;
  logic [32-1:0] sts_frames;
  logic [32-1:0] sts_count;
  logic [32-1:0] sts_box_x;
  logic [32-1:0] sts_box_y;
  logic [32-1:0] sts_sum_x;
  logic [32-1:0] sts_sum_y;
  logic [32-1:0] sts_status;
  logic [32-1:0] cfg_run;
  logic cfg_run_wr;
  logic [16-1:0] cfg_y_range;
  logic cfg_y_range_wr;
  logic [16-1:0] cfg_cb_range;
  logic cfg_cb_range_wr;
  logic [16-1:0] cfg_cr_range;
  logic cfg_cr_range_wr;
  logic [8-1:0] cfg_sat_min;
  logic cfg_sat_min_wr;
  logic [32-1:0] cfg_blob_cfg;
  logic cfg_blob_cfg_wr;
  logic [(28)*(32)-1:0] cfg_scratch;
  logic [28-1:0] cfg_scratch_wr;
  logic [32-1:0] cfg_run_b;
  logic cfg_run_b_wr;
  logic [(8)*(32)-1:0] sts_blob_x;
  logic [(8)*(32)-1:0] sts_blob_y;
  logic [(8)*(32)-1:0] sts_blob_n;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr, cfg_thresh, cfg_thresh_wr,
    cfg_win_x, cfg_win_x_wr, cfg_win_y, cfg_win_y_wr, cfg_run, cfg_run_wr, cfg_y_range, cfg_y_range_wr,
    cfg_cb_range, cfg_cb_range_wr, cfg_cr_range, cfg_cr_range_wr, cfg_sat_min, cfg_sat_min_wr, cfg_blob_cfg,
    cfg_blob_cfg_wr, cfg_scratch, cfg_scratch_wr, cfg_run_b, cfg_run_b_wr, input sts_frames, sts_count,
    sts_box_x, sts_box_y, sts_sum_x, sts_sum_y, sts_status, sts_blob_x, sts_blob_y, sts_blob_n);
  modport core (output sts_frames, sts_count, sts_box_x, sts_box_y, sts_sum_x, sts_sum_y, sts_status,
    sts_blob_x, sts_blob_y, sts_blob_n, input cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr,
    cfg_thresh, cfg_thresh_wr, cfg_win_x, cfg_win_x_wr, cfg_win_y, cfg_win_y_wr, cfg_run, cfg_run_wr,
    cfg_y_range, cfg_y_range_wr, cfg_cb_range, cfg_cb_range_wr, cfg_cr_range, cfg_cr_range_wr, cfg_sat_min,
    cfg_sat_min_wr, cfg_blob_cfg, cfg_blob_cfg_wr, cfg_scratch, cfg_scratch_wr, cfg_run_b, cfg_run_b_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_frame_size, cfg_frame_size_wr, cfg_thresh, cfg_thresh_wr,
    cfg_win_x, cfg_win_x_wr, cfg_win_y, cfg_win_y_wr, cfg_run, cfg_run_wr, cfg_y_range, cfg_y_range_wr,
    cfg_cb_range, cfg_cb_range_wr, cfg_cr_range, cfg_cr_range_wr, cfg_sat_min, cfg_sat_min_wr, cfg_blob_cfg,
    cfg_blob_cfg_wr, cfg_scratch, cfg_scratch_wr, cfg_run_b, cfg_run_b_wr, sts_frames, sts_count, sts_box_x,
    sts_box_y, sts_sum_x, sts_sum_y, sts_status, sts_blob_x, sts_blob_y, sts_blob_n);
endinterface
